const row = $input.first().json || {};
  const config = $('Authenticate Dashboard').item.json || {};
  function number(value) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : 0;
  }
  function object(value, fallback) {
    if (value && typeof value === 'object') return value;
    try { return JSON.parse(String(value || '')); } catch (error) { return fallback; }
  }
  function escape(value) {
    return String(value ?? '').replace(/[&<>"']/g, (character) => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
    })[character]);
  }
  function formatSeconds(value) {
    const seconds = number(value);
    if (seconds < 60) return `${seconds}s`;
    if (seconds < 3600) return `${Math.floor(seconds / 60)}m`;
    return `${Math.floor(seconds / 3600)}h ${Math.floor((seconds % 3600) / 60)}m`;
  }
  function rowsFromObject(value) {
    const entries = Object.entries(object(value, {}));
    if (!entries.length) return '<tr><td colspan="2" class="muted">Sin datos</td></tr>';
    return entries.map(([key, total]) => `<tr><td><code>${escape(key)}</code></td><td>${number(total)}</td></tr>`).join('');
  }
  const llmProviders = object(row.llm_providers, []);
  const llmRows = Array.isArray(llmProviders) && llmProviders.length
    ? llmProviders.map((provider) => `<tr><td>${escape(provider.provider)}</td><td>${number(provider.attempts)}</td><td>${number(provider.failures)}</td><td>${number(provider.average_latency_ms)} ms</td><td>${number(provider.p95_latency_ms)} ms</td></tr>`).join('')
    : '<tr><td colspan="5" class="muted">Sin intentos en la ventana</td></tr>';
  const alertClass = config.alert_webhook_configured ? 'ok' : 'warn';
  const alertText = config.alert_webhook_configured ? 'Webhook configurado' : 'Webhook pendiente';
  const generatedAt = row.generated_at ? new Date(row.generated_at).toLocaleString('es-EC', { timeZone: 'America/Guayaquil' }) : '-';
  const startsAt = row.starts_at ? new Date(row.starts_at).toLocaleString('es-EC', { timeZone: 'America/Guayaquil' }) : '-';
  const html = `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Renovaciones | Observabilidad</title><style>
    :root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:#09111f;color:#eaf0f8}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 90% 0,#173a4f 0,transparent 34%),#09111f;padding:28px}.shell{max-width:1180px;margin:auto}header{display:flex;gap:24px;justify-content:space-between;align-items:end;margin-bottom:24px}h1{font-size:clamp(1.8rem,4vw,3.2rem);margin:0;letter-spacing:-.04em}header p{margin:8px 0 0;color:#93a6bd}.status{display:inline-flex;align-items:center;border-radius:99px;padding:8px 12px;font-weight:800;font-size:.82rem}.ok{background:#123d32;color:#76edc7}.warn{background:#4a3317;color:#ffd08a}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card,.panel{background:#101d2fdd;border:1px solid #263d58;border-radius:16px}.card{padding:18px}.card span{display:block;color:#91a5bd;font-size:.78rem;text-transform:uppercase;letter-spacing:.08em}.card strong{display:block;font-size:2rem;margin-top:8px}.card small{color:#91a5bd}.grid{display:grid;grid-template-columns:1.2fr .8fr;gap:14px;margin-top:14px}.panel{padding:20px;overflow:auto}h2{margin:0 0 14px;font-size:1.05rem}table{width:100%;border-collapse:collapse;font-size:.9rem}th,td{text-align:left;padding:10px;border-bottom:1px solid #24364d}th{color:#8ea2ba;font-size:.72rem;text-transform:uppercase;letter-spacing:.07em}.muted{color:#8295ac}.queues{display:grid;grid-template-columns:1fr 1fr;gap:14px}.queue{padding:14px;background:#0b1626;border-radius:12px}.queue strong{font-size:1.4rem}.footer{margin-top:18px;color:#7f93aa;font-size:.78rem}code{color:#8ce7cc}@media(max-width:850px){body{padding:16px}header{display:block}.status{margin-top:14px}.cards{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}}@media(max-width:520px){.cards,.queues{grid-template-columns:1fr}}</style></head><body><main class="shell">
    <header><div><h1>Piloto Renovaciones</h1><p>Ventana de ${number(row.window_hours)} horas · ${escape(startsAt)} a ${escape(generatedAt)}</p></div><div><span class="status ${alertClass}">${alertText}</span></div></header>
    <section class="cards">
      <article class="card"><span>Respuestas inbound</span><strong>${number(row.inbound_messages)}</strong><small>${number(row.responding_conversations)} conversaciones</small></article>
      <article class="card"><span>Mensajes bot aceptados</span><strong>${number(row.bot_messages_accepted)}</strong><small>${number(row.bot_messages_delivered)} entregados o leídos</small></article>
      <article class="card"><span>Handoffs exitosos</span><strong>${number(row.successful_handoffs)}</strong><small>${number(row.resolved_handoffs)} resueltos</small></article>
      <article class="card"><span>Fallos operativos</span><strong>${number(row.interaction_failures)}</strong><small>${number(row.double_llm_failures)} fallos dobles LLM</small></article>
    </section>
    <section class="grid"><article class="panel"><h2>LLM por proveedor</h2><table><thead><tr><th>Proveedor</th><th>Intentos</th><th>Fallos</th><th>Promedio</th><th>P95</th></tr></thead><tbody>${llmRows}</tbody></table></article>
      <article class="panel"><h2>Colas actuales</h2><div class="queues"><div class="queue"><span class="muted">Dispatch</span><p><strong>${number(row.dispatch_queued)}</strong> en cola</p><small>${number(row.dispatch_running)} running · ${number(row.dispatch_failed)} failed · más antiguo ${formatSeconds(row.dispatch_oldest_queued_seconds)}</small></div><div class="queue"><span class="muted">Callbacks Salesforce</span><p><strong>${number(row.callback_queued)}</strong> en cola</p><small>${number(row.callback_running)} running · ${number(row.callback_failed)} failed · más antiguo ${formatSeconds(row.callback_oldest_queued_seconds)}</small></div></div></article></section>
    <section class="grid"><article class="panel"><h2>Fallos por evento</h2><table><tbody>${rowsFromObject(row.failures_by_event)}</tbody></table></article><article class="panel"><h2>Conversaciones por estado</h2><table><tbody>${rowsFromObject(row.conversations_by_status)}</tbody></table></article></section>
    <section class="grid"><article class="panel"><h2>Campaña HSM</h2><table><tbody><tr><td>Items</td><td>${number(row.hsm_items)}</td></tr><tr><td>Aceptados</td><td>${number(row.hsm_accepted)}</td></tr><tr><td>Entregados o leídos</td><td>${number(row.hsm_delivered)}</td></tr><tr><td>Fallidos</td><td>${number(row.hsm_failed)}</td></tr></tbody></table></article><article class="panel"><h2>Guardas</h2><table><tbody><tr><td>Ventana automática abierta</td><td>${row.automatic_send_allowed === true ? 'Sí' : 'No'}</td></tr><tr><td>Dispatch estancados</td><td>${number(row.dispatch_stalled)}</td></tr><tr><td>Callbacks estancados</td><td>${number(row.callback_stalled)}</td></tr><tr><td>Takeovers humanos</td><td>${number(row.human_takeovers)}</td></tr></tbody></table></article></section>
    <p class="footer">Solo métricas agregadas. No muestra nombres, teléfonos, mensajes, payloads ni errores crudos. Cache deshabilitada.</p>
  </main></body></html>`;
  return [{ json: { statusCode: 200, html } }];

const input = $input.first().json || {};
  const statusCode = Number(input.statusCode || 401);
  const isLogin = statusCode === 401;
  const title = isLogin ? 'Acceso operativo' : 'Tablero no disponible';
  const detail = statusCode === 503
    ? 'RENOV_INTERNAL_TOKEN no está configurado en el runtime.'
    : (statusCode === 422
      ? 'El parámetro hours debe ser un entero entre 1 y 168.'
      : 'Ingrese el token interno. No se guarda en la URL ni en el navegador.');
  const form = isLogin ? `<form id="login">
    <label for="token">Token interno</label>
    <input id="token" name="token" type="password" autocomplete="off" required>
    <button type="submit">Abrir tablero</button>
    <p id="error" role="alert"></p>
  </form>
  <script>
    document.getElementById('login').addEventListener('submit', async function (event) {
      event.preventDefault();
      const error = document.getElementById('error');
      error.textContent = '';
      try {
        const token = document.getElementById('token').value;
        const response = await fetch(location.pathname + location.search, {
          headers: { Authorization: 'Bearer ' + token },
          cache: 'no-store'
        });
        if (!response.ok) throw new Error('Acceso rechazado (' + response.status + ').');
        const html = await response.text();
        document.open(); document.write(html); document.close();
      } catch (requestError) {
        error.textContent = requestError.message || 'No se pudo abrir el tablero.';
      }
    });
  </script>` : '';
  const html = `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title><style>
    :root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:#0b1220;color:#e7edf7}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px}.panel{width:min(440px,100%);background:#121d30;border:1px solid #29405f;border-radius:18px;padding:28px;box-shadow:0 24px 70px #02061180}h1{margin:0 0 8px;font-size:1.6rem}p{color:#aab8ca;line-height:1.5}label{display:block;margin:22px 0 8px;font-weight:700}input{box-sizing:border-box;width:100%;padding:12px;border-radius:10px;border:1px solid #3b5578;background:#08101d;color:#fff}button{margin-top:14px;width:100%;padding:12px;border:0;border-radius:10px;background:#33d6a6;color:#06140f;font-weight:800;cursor:pointer}#error{color:#ff9c9c;min-height:1.5em}</style></head><body><main class="panel"><h1>${title}</h1><p>${detail}</p>${form}</main></body></html>`;
  return [{ json: { statusCode, html } }];
